package com.cyberattack.soc.model;

import com.cyberattack.soc.model.enums.AlertStatus;
import com.cyberattack.soc.model.enums.DataSource;
import com.cyberattack.soc.model.enums.RiskLevel;
import com.fasterxml.jackson.annotation.JsonBackReference;
import com.fasterxml.jackson.annotation.JsonManagedReference;
import com.fasterxml.jackson.annotation.JsonProperty;
import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Represents a security threat alert generated by the detection pipeline.
 */
@Entity
@Table(name = "threat_alerts")
public class ThreatAlert {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private DataSource dataSource;

    @Column(nullable = false)
    private LocalDateTime timestamp;

    @Column(nullable = false)
    private Double riskScore;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private RiskLevel riskLevel;

    @Column(nullable = false, length = 60)
    private String attackType;

    @Column(nullable = false)
    private Double confidence;

    @NotNull
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private AlertStatus status;

    @Column(nullable = false, length = 45)
    private String sourceIp;

    @Column(nullable = false, length = 45)
    private String destinationIp;

    @Column(nullable = false)
    private Integer sourcePort;

    @Column(nullable = false)
    private Integer destinationPort;

    @Column(nullable = false, length = 10)
    private String protocol;

    private Boolean ruleTriggered = false;
    private Boolean mlTriggered = false;

    @Column(length = 2000)
    private String explanationNarrative;

    private Double anomalyScore;

    @OneToMany(mappedBy = "threatAlert", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JsonManagedReference
    private List<PreventionAction> preventionActions = new ArrayList<>();

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "incident_id")
    @JsonBackReference
    private Incident incident;

    // Constructors
    public ThreatAlert() {
        this.timestamp = LocalDateTime.now();
        this.status = AlertStatus.NEW;
        this.dataSource = DataSource.OBSERVED;
    }

    public ThreatAlert(DataSource dataSource, Double riskScore, RiskLevel riskLevel,
                       String attackType, Double confidence, String sourceIp,
                       String destinationIp, Integer sourcePort, Integer destinationPort,
                       String protocol, Boolean ruleTriggered, Boolean mlTriggered,
                       String explanationNarrative) {
        this();
        this.dataSource = dataSource;
        this.riskScore = riskScore;
        this.riskLevel = riskLevel;
        this.attackType = attackType;
        this.confidence = confidence;
        this.sourceIp = sourceIp;
        this.destinationIp = destinationIp;
        this.sourcePort = sourcePort;
        this.destinationPort = destinationPort;
        this.protocol = protocol;
        this.ruleTriggered = ruleTriggered;
        this.mlTriggered = mlTriggered;
        this.explanationNarrative = explanationNarrative;
    }

    // Helper method to add prevention action
    public void addPreventionAction(PreventionAction action) {
        preventionActions.add(action);
        action.setThreatAlert(this);
    }

    // Encapsulation
    public UUID getId() {
        return id;
    }

    public void setId(UUID id) {
        this.id = id;
    }

    public DataSource getDataSource() {
        return dataSource;
    }

    public void setDataSource(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(LocalDateTime timestamp) {
        this.timestamp = timestamp;
    }

    public Double getRiskScore() {
        return riskScore;
    }

    public void setRiskScore(Double riskScore) {
        this.riskScore = riskScore;
    }

    public RiskLevel getRiskLevel() {
        return riskLevel;
    }

    public void setRiskLevel(RiskLevel riskLevel) {
        this.riskLevel = riskLevel;
    }

    public String getAttackType() {
        return attackType;
    }

    public void setAttackType(String attackType) {
        this.attackType = attackType;
    }

    public Double getConfidence() {
        return confidence;
    }

    public void setConfidence(Double confidence) {
        this.confidence = confidence;
    }

    public AlertStatus getStatus() {
        return status;
    }

    public void setStatus(AlertStatus status) {
        this.status = status;
    }

    public String getSourceIp() {
        return sourceIp;
    }

    public void setSourceIp(String sourceIp) {
        this.sourceIp = sourceIp;
    }

    public String getDestinationIp() {
        return destinationIp;
    }

    public void setDestinationIp(String destinationIp) {
        this.destinationIp = destinationIp;
    }

    public Integer getSourcePort() {
        return sourcePort;
    }

    public void setSourcePort(Integer sourcePort) {
        this.sourcePort = sourcePort;
    }

    public Integer getDestinationPort() {
        return destinationPort;
    }

    public void setDestinationPort(Integer destinationPort) {
        this.destinationPort = destinationPort;
    }

    public String getProtocol() {
        return protocol;
    }

    public void setProtocol(String protocol) {
        this.protocol = protocol;
    }

    public Boolean getRuleTriggered() {
        return ruleTriggered;
    }

    public void setRuleTriggered(Boolean ruleTriggered) {
        this.ruleTriggered = ruleTriggered;
    }

    public Boolean getMlTriggered() {
        return mlTriggered;
    }

    public void setMlTriggered(Boolean mlTriggered) {
        this.mlTriggered = mlTriggered;
    }

    public String getExplanationNarrative() {
        return explanationNarrative;
    }

    public void setExplanationNarrative(String explanationNarrative) {
        this.explanationNarrative = explanationNarrative;
    }

    public Double getAnomalyScore() {
        return anomalyScore;
    }

    public void setAnomalyScore(Double anomalyScore) {
        this.anomalyScore = anomalyScore;
    }

    public List<PreventionAction> getPreventionActions() {
        return preventionActions;
    }

    public void setPreventionActions(List<PreventionAction> preventionActions) {
        this.preventionActions = preventionActions;
    }

    public Incident getIncident() {
        return incident;
    }

    public void setIncident(Incident incident) {
        this.incident = incident;
    }

    // Frontend compatibility aliases
    @JsonProperty("src_ip")
    public String getSrcIp() {
        return sourceIp;
    }

    @JsonProperty("dst_ip")
    public String getDstIp() {
        return destinationIp;
    }

    @JsonProperty("src_port")
    public Integer getSrcPort() {
        return sourcePort;
    }

    @JsonProperty("dst_port")
    public Integer getDstPort() {
        return destinationPort;
    }

    @JsonProperty("explanation")
    public Map<String, Object> getExplanation() {
        Map<String, Object> map = new HashMap<>();
        map.put("narrative", explanationNarrative != null ? explanationNarrative : "Anomalous flow signature detected across network volume and protocol metrics.");
        map.put("anomaly_score", anomalyScore != null ? anomalyScore : 0.0);
        map.put("risk_score", riskScore != null ? riskScore : 0.0);
        map.put("top_features", Collections.emptyList());
        return map;
    }

    @JsonProperty("mitigations")
    public List<Map<String, Object>> getMitigations() {
        if (preventionActions == null) return Collections.emptyList();
        return preventionActions.stream().map(a -> {
            Map<String, Object> m = new HashMap<>();
            m.put("action_type", a.getActionType() != null ? a.getActionType().name() : "BLOCK_IP");
            m.put("target_ip", a.getTargetIp());
            m.put("generated_script", a.getGeneratedScript());
            m.put("status", a.getStatus());
            m.put("created_at", a.getCreatedAt() != null ? a.getCreatedAt().toString() : "");
            return m;
        }).collect(Collectors.toList());
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ThreatAlert that = (ThreatAlert) o;
        return Objects.equals(id, that.id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }

    @Override
    public String toString() {
        return "ThreatAlert{" +
                "id=" + id +
                ", attackType='" + attackType + '\'' +
                ", riskScore=" + riskScore +
                ", riskLevel=" + riskLevel +
                ", status=" + status +
                '}';
    }
}
